/* Checks that simulated time keeps pace with the host clock. Each simulated timer
   interrupt is TX_TIMER_PERIODIC host milliseconds and TX_WIN32_TICKS_PER_INTERRUPT
   ticks, so a sleep of two seconds' worth of ticks must take two host seconds.
   Interrupt latency that accumulates into the period makes it take longer.  */

#include <stdio.h>
#include <stdlib.h>
#include <windows.h>
#include "tx_api.h"


/* The SMP port processes one tick per interrupt.  */
#ifndef TX_WIN32_TICKS_PER_INTERRUPT
#define TX_WIN32_TICKS_PER_INTERRUPT    1
#endif

#define TEST_TICKS_PER_SECOND       ((TX_WIN32_TICKS_PER_INTERRUPT * 1000UL) / TX_TIMER_PERIODIC)
#define TEST_SLEEP_TICKS            (2UL * TEST_TICKS_PER_SECOND)
#define TEST_TOLERANCE_PERCENT      2U


static TX_THREAD        test_thread;
static ULONG            test_stack[4096 / sizeof(ULONG)];


static VOID test_entry(ULONG input)
{
LARGE_INTEGER   frequency;
LARGE_INTEGER   start;
LARGE_INTEGER   end;
ULONG           start_ticks;
ULONG           ticks;
double          ticks_per_second;
double          expected;

    (VOID) input;

    /* Start on an interrupt boundary.  */
    tx_thread_sleep(1);

    (VOID) QueryPerformanceFrequency(&frequency);
    start_ticks =  tx_time_get();
    (VOID) QueryPerformanceCounter(&start);
    tx_thread_sleep(TEST_SLEEP_TICKS);
    (VOID) QueryPerformanceCounter(&end);
    ticks =  tx_time_get() - start_ticks;

    ticks_per_second =  ((double) ticks * (double) frequency.QuadPart) / (double) (end.QuadPart - start.QuadPart);
    expected =          (double) TEST_TICKS_PER_SECOND;

    if ((ticks_per_second < ((expected * (100U - TEST_TOLERANCE_PERCENT)) / 100.0)) ||
        (ticks_per_second > ((expected * (100U + TEST_TOLERANCE_PERCENT)) / 100.0)))
    {
        printf("Running Windows simulator tick rate test............................ ERROR!\n");
        printf("  %.1f ticks/s, expected %.1f\n", ticks_per_second, expected);
        exit(1);
    }

    printf("Running Windows simulator tick rate test............................ SUCCESS!\n");
    printf("  %.1f ticks/s, expected %.1f\n", ticks_per_second, expected);
    exit(0);
}


VOID tx_application_define(VOID *first_unused_memory)
{
    (VOID) first_unused_memory;

    (VOID) tx_thread_create(&test_thread, "tick rate", test_entry, 0,
                            test_stack, sizeof(test_stack), 1, 1, TX_NO_TIME_SLICE, TX_AUTO_START);
}


int main(void)
{
    tx_kernel_enter();
    return 0;
}
